/**
 * Generated by localize.dev. useLanguage(Astro.url): the language of a page and the ones this site offers.
 * Options: languages (codes, in order), nameStyle ("native" | "english" | "code" | "native-english"),
 * compact, hideFlag, align ("start" | "end"), side ("bottom" | "top"), label. Restyle it with the
 * --ldv-* CSS variables or ::part(button|menu|option|flag). https://uselocalize.dev/docs#switcher
 */
import { languageState } from 'localize-dev/switcher';
import { getLangFromUrl, languages, localizePath } from './index';

/** The page's language (code, info with flag and names, the list, dir), and each language's URL for this page. */
export function useLanguage(url: URL) {
  return {
    ...languageState(getLangFromUrl(url), languages),
    href: (lang: string) => localizePath(url.pathname, lang),
  };
}
